const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10H3z"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',file:'<path d="M14 2H5v20h14V7zM14 2v5h5M8 12h8M8 16h8"/>',book:'<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1zm0 0v15"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',layers:'<path d="m12 3 10 5-10 5L2 8zm-10 9 10 5 10-5M2 16l10 5 10-5"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-15a3 3 0 0 1 0 6m5 9v-3a6 6 0 0 0-3-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',upload:'<path d="M12 16V3m-4 4 4-4 4 4M4 16v5h16v-5"/>',chevron:'<path d="m14 6-6 6 6 6"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12"/><circle cx="12" cy="12" r="3"/>',alert:'<path d="m12 3 10 18H2zM12 9v5m0 3v.1"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1.5"/><path d="m21 15-5-5L5 21"/>',leaf:'<path d="M5 19C-3 5 14 3 21 3c0 10-3 19-16 16zm0 0L17 7"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.file}</svg>`;
let workspaceKey='state';
let db,state={projects:[],exports:[]},view='dashboard',activeId=null,step=0,search='',typeFilter='all',teamFilter='all',saveChain=Promise.resolve(),saveTimer,toastTimer,unsaved=false,editRevision=0;
const steps=['专利信息','申请人与发明人','技术说明','权利要求','摘要与附图','检查与导出'];
const person=()=>({name:'',country:'中国',idNumber:'',privateName:false});
const applicant=()=>({name:'',kind:'个人',country:'中国',idNumber:'',email:'',phone:'',residence:'中国',postcode:'',province:'',city:'',address:''});
const contact=()=>({name:'',phone:'',email:'',province:'',city:'',address:'',postcode:''});
const blank=()=>({id:crypto.randomUUID(),title:'',team:'',type:'invention',inventors:[person()],applicants:[applicant()],contact:contact(),technicalField:'',background:'',problem:'',solution:'',benefits:'',embodiments:'',claims:[{text:''}],abstract:'',figures:[],abstractFigure:1,earlyPublication:false,substantive:'none',feeReduction:false,sameDay:false,applicationNumber:'',signDate:'',pageCounts:{request:'',claims:'',description:'',abstract:'',drawings:'',substantive:''},createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),example:false});
function sample(){return {...blank(),title:'专利填写示例 · 从这里开始',team:'康莱德 · 填写演示',example:true};}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('zhixu-patent-studio',1);r.onupgradeneeded=()=>r.result.createObjectStore('workspace');r.onerror=()=>reject(r.error);r.onsuccess=()=>resolve(r.result);});}
function readDB(key=workspaceKey){return new Promise((resolve,reject)=>{const r=db.transaction('workspace').objectStore('workspace').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function writeDB(data,key=workspaceKey){return new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(data,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
function saveStatus(s,good=true){const e=$('#save-status');if(e){e.innerHTML=icon(good?'check':'alert')+esc(s);e.style.color=good?'':'#b84747';}}
function queueSave(){editRevision++;unsaved=true;saveStatus('正在保存…');clearTimeout(saveTimer);saveTimer=setTimeout(persist,350);}
async function persist(){clearTimeout(saveTimer);const snapshot=structuredClone(state),revision=editRevision,key=workspaceKey;saveChain=saveChain.catch(()=>{}).then(()=>writeDB(snapshot,key));try{await saveChain;if(revision===editRevision){unsaved=false;saveStatus('已保存到此浏览器');}}catch(e){unsaved=true;saveStatus('保存失败，请立即备份',false);toast('浏览器存储失败，请下载备份以免丢失。');throw e;}}
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function current(){return state.projects.find(p=>p.id===activeId);}
function touch(){const p=current();if(p){p.updatedAt=new Date().toISOString();queueSave();updateLive();}}
function fmtDate(d){try{return new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Shanghai'}).format(new Date(d));}catch{return '刚刚';}}
function issues(p){const out=[];const add=(message,step,severity='error')=>out.push({message,step,severity});if(!p.title.trim())add('填写发明创造名称',0);else if(p.title.length>60)add('名称超过 60 个字，请精简',0);else if(p.title.length>25)add('名称超过通常建议的 25 字，请确认确有必要',0,'warning');if(!p.team.trim())add('填写康莱德队伍名称，便于归档',0,'warning');
if(!p.inventors.length)add('至少填写一位发明人',1);p.inventors.forEach((v,i)=>{if(!v.name.trim())add(`填写第 ${i+1} 位发明人的姓名`,1);if(!v.country.trim())add(`填写第 ${i+1} 位发明人的国籍或地区`,1);if(v.country==='中国'&&!v.idNumber.trim())add(`补齐第 ${i+1} 位发明人的身份证件号码`,1);if(v.idNumber&&!/^(\d{17}[\dXx]|[A-Za-z0-9\-]{6,30})$/.test(v.idNumber))add(`核对第 ${i+1} 位发明人的证件号码格式`,1,'warning');});
p.applicants.forEach((v,i)=>{const fields={name:'姓名或名称',idNumber:'证件号码',province:'省份',city:'市县',address:'详细地址',postcode:'邮政编码',phone:'电话',country:'国籍或注册地区'};for(const [k,label]of Object.entries(fields))if(!v[k]?.trim())add(`补齐申请人 ${i+1} 的${label}`,1);if(v.postcode&&!/^\d{6}$/.test(v.postcode))add(`申请人 ${i+1} 的国内邮编应为 6 位数字`,1);if(v.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.email))add(`申请人 ${i+1} 的邮箱格式需要核对`,1);});
if(p.applicants.some(a=>a.kind!=='个人'))for(const k of ['name','phone','email','province','city','address','postcode'])if(!p.contact[k]?.trim())add('单位申请且未委托代理时，请补齐联系人姓名、电话、邮箱和通信地址',1);if(p.contact.name){for(const k of ['phone','email','province','city','address','postcode'])if(!p.contact[k]?.trim())add('已填写联系人，请补齐其电话、邮箱和完整通信地址',1);}const required={technicalField:'技术领域',background:'背景技术',problem:'要解决的技术问题',solution:'技术方案',benefits:'有益效果',embodiments:'具体实施方式'};for(const[k,label]of Object.entries(required))if(!p[k].trim())add(`填写${label}`,2);
if(!p.claims.length||!p.claims[0].text.trim())add('至少填写一项独立权利要求',3);p.claims.forEach((c,i)=>{if(!c.text.trim())add(`权利要求 ${i+1} 为空`,3);if(/^\s*\d+[.、．]/.test(c.text))add(`权利要求 ${i+1} 已含手写序号，导出会去掉重复序号`,3,'warning');const refs=[...c.text.matchAll(/权利要求\s*(\d+)/g)];if(refs.some(r=>+r[1]>=i+1))add(`权利要求 ${i+1} 引用了自身或后面的权项，请调整`,3);if(p.type==='utility'&&/^\s*(?:\d+[.、．]\s*)?一种[^。；]*方法/.test(c.text))add(`实用新型的权利要求 ${i+1} 以方法为主题，需要改为产品形状、构造或其结合`,3);});
if(!p.abstract.trim())add('填写说明书摘要',4);else if([...p.abstract].length>300)add(`摘要为 ${[...p.abstract].length} 字，超过 300 字`,4);if(p.type==='utility'&&!p.figures.length)add('实用新型必须上传体现产品形状、构造的附图',4);p.figures.forEach((f,i)=>{if(!f.caption.trim())add(`填写图 ${i+1} 的附图说明`,4);if(!/^data:image\/(png|jpeg);base64,/.test(f.dataUrl))add(`图 ${i+1} 的图片数据无效`,4);if(Math.min(f.width||0,f.height||0)<600)add(`图 ${i+1} 分辨率偏低，缩印后请核对细节可读性`,4,'warning');});if(p.figures.length&&(+p.abstractFigure<1||+p.abstractFigure>p.figures.length))add('指定一个有效的摘要附图图号',4);if(p.type==='utility'&&/方法|算法/.test(p.title))add('实用新型名称包含“方法”或“算法”，请核对保护主题',0,'warning');if(p.type==='invention'&&p.substantive==='separate'&&!p.applicationNumber.trim())add('单独提出实审请求时，请填写已有的申请号',0);if(!p.signDate)add('签署日期尚未填写，签署前补齐',0,'warning');
return out.filter((x,i,a)=>a.findIndex(y=>y.message===x.message)===i);}
function progress(p){const blocks=[!!p.title,!!p.team,p.inventors.every(v=>v.name&&v.idNumber),p.applicants.every(v=>v.name&&v.idNumber&&v.address),...['technicalField','background','problem','solution','benefits','embodiments','abstract'].map(k=>!!p[k].trim()),p.claims.every(c=>!!c.text.trim()),p.type==='invention'||p.figures.length>0];return Math.round(blocks.filter(Boolean).length/blocks.length*100);}
function docNames(p){return[p.type==='utility'?'实用新型专利请求书':'发明专利请求书','权利要求书','说明书','说明书摘要',...(p.figures.length?['说明书附图','摘要附图']:[]),...(p.inventors.length>2?['发明人附页']:[]),...(p.type==='invention'&&p.substantive==='separate'?['实质审查请求书']:[])];}
function statusPill(p){const n=issues(p).filter(x=>x.severity==='error').length;return `<span class="pill ${n?'orange':'green'}">${p.example?'参考示例':n?'待完善':'可导出审阅包'}</span>`;}
function shell(inner,title){return `<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">${icon('layers')}</div><div><strong>康莱德工坊</strong><small>PATENT WORKSHOP</small></div></div><div class="workspace"><span class="avatar">康</span><span>康莱德工坊</span></div><div class="navlabel">专利申请</div>${[['dashboard','grid','专利概览'],['projects','folder','全部专利'],['exports','download','专利导出'],['standards','book','专利模板与规范']].map(([v,i,n])=>`<button class="navbutton ${view===v?'active':''}" data-nav="${v}" title="${n}">${icon(i)}<span>${n}</span>${v==='projects'?`<span class="navcount">${state.projects.length}</span>`:''}</button>`).join('')}<div class="sidebar-bottom"><button class="navbutton" data-action="backup" title="备份专利资料">${icon('download')}<span>备份专利资料</span></button><button class="navbutton" data-action="import" title="导入备份">${icon('upload')}<span>导入备份</span></button><div class="save-note"><strong>${icon('shield')} 本地保存，随时备份</strong>材料保存在当前浏览器<br>更换设备前请导出备份</div><div class="profile"><span class="profile-icon">康</span><div style="font-size:13px">康莱德工坊 · 专利申请<small>CONRAD PATENTS</small></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb"><span>康莱德工坊</span><span>/</span><strong>${title}</strong></div><div class="top-actions">${window.PatentAI?.header()||''}<span class="saved" id="save-status">${icon('check')}已保存到此浏览器</span><span class="date">${new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'long',day:'numeric',timeZone:'Asia/Shanghai'}).format(new Date())}</span></div></header><div class="content">${inner}<div class="footer"><span>康莱德工坊 · 专利申请材料生成</span><span>Word 编制与审阅 · 申报请使用官方系统</span></div></div></main></div>`;}
function render(){let body,title;switch(view){case'editor':if(!current()){view='dashboard';return render();}body=editor();title='专利编制';break;case'projects':body=projects();title='全部专利';break;case'exports':body=exportsView();title='专利导出';break;case'standards':body=standards();title='专利模板与规范';break;default:body=dashboard();title='专利概览';}$('#app').innerHTML=shell(body,title);if(unsaved)saveStatus('正在保存…');}
function table(){const ps=state.projects.filter(p=>(!search||`${p.title} ${p.team}`.toLowerCase().includes(search.toLowerCase()))&&(typeFilter==='all'||p.type===typeFilter)&&(teamFilter==='all'||p.team===teamFilter)).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));return ps.length?`<table class="project-table"><thead><tr><th>专利名称</th><th>申请类型</th><th class="hide-medium">填写进度</th><th class="hide-small">状态</th><th class="hide-medium">最近更新</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><div class="project-title"><div class="project-icon">${icon('file')}</div><button data-open="${p.id}"><strong>${esc(p.title||'未命名课题')}</strong><small>${esc(p.team||'未设置队伍')} ${p.example?'· 通用填写示例':''}</small></button></div></td><td><span class="pill">${p.type==='utility'?'实用新型':'发明专利'}</span></td><td class="hide-medium"><div class="progress-caption">${progress(p)}%</div><div class="progress"><span style="width:${progress(p)}%"></span></div></td><td class="hide-small">${statusPill(p)}</td><td class="hide-medium" style="font-size:12px;color:#839399;white-space:nowrap">${fmtDate(p.updatedAt)}</td><td><button class="btn small" data-open="${p.id}">继续填写</button></td></tr>`).join('')}</tbody></table>`:`<div class="empty">${icon('folder')}<h3>${search||typeFilter!=='all'||teamFilter!=='all'?'没有匹配的课题':'从你的第一个课题开始'}</h3><p>把团队的创意整理成一套有序的申请材料。</p><button class="btn primary" data-action="new">${icon('plus')}新建专利</button></div>`;}
function toolbar(){return `<div class="toolbar"><label class="search">${icon('search')}<input id="search" placeholder="搜索专利或队伍" aria-label="搜索专利或队伍" value="${esc(search)}"></label><select class="select-small" id="type-filter" aria-label="筛选专利类型"><option value="all">全部类型</option><option value="invention" ${typeFilter==='invention'?'selected':''}>发明专利</option><option value="utility" ${typeFilter==='utility'?'selected':''}>实用新型</option></select></div>`;}
function dashboard(){const teams=new Set(state.projects.filter(p=>!p.example&&p.team).map(p=>p.team)).size, ready=state.projects.filter(p=>!p.example&&!issues(p).some(x=>x.severity==='error')).length;return `<div class="heading-line"><div><div class="eyebrow">PATENT APPLICATION WORKSHOP</div><h1>专利申请，从这里开始。</h1><p class="subtitle">为康莱德团队编制发明专利、实用新型专利申请材料。</p></div><button class="btn primary" data-action="new">${icon('plus')}新建专利</button></div><section class="hero"><div class="hero-copy"><div class="hero-tag">${icon('leaf')} 康莱德工坊 · 专利材料生成器</div><h2>填写一次，整理一整套专利材料。</h2><p>用引导式表单梳理技术方案，让申请信息、权利要求、说明书与附图各就其位。</p><div class="hero-links"><button class="btn lime" data-action="new">开始编制专利</button><button class="btn text" data-nav="standards">查看专利模板与排版规范</button></div></div><div class="paper-scene" aria-hidden="true"><div class="paper back"></div><div class="paper"><b>说 明 书</b><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="paper-stamp">${icon('check')}</div></div></section><section class="ai-entry"><div><div class="eyebrow">FROM FILES TO PATENT DRAFT</div><h3>上传技术材料，让 AI 帮你起草专利。</h3><p>多份文件一起梳理，自动检查技术说明、权利要求与摘要，直接生成 Word 材料包。</p></div><button class="btn primary" data-ai="start">上传材料 · AI 整理 →</button></section><div class="stats">${[[state.projects.filter(p=>!p.example).length,'在编专利','folder','参考示例不计入'],[teams,'康莱德队伍','people','按队伍归档多个课题'],[ready,'基础信息已齐','shield','可生成 Word 审阅包'],[state.exports.length,'导出记录','download','当前浏览器的生成记录']].map(([n,l,i,b])=>`<div class="stat"><div class="stat-top"><span>${l}</span>${icon(i)}</div><div class="stat-num">${String(n).padStart(2,'0')}<small>${l==='导出记录'?'次':'个'}</small></div><div class="stat-bottom">${b}</div></div>`).join('')}</div><div class="section-head"><h2>最近的专利 <span>${state.projects.length} 个课题</span></h2>${toolbar()}</div><div class="panel" id="project-results">${table()}</div><div class="bottom-grid"><div class="panel bottom-card"><h3>从技术方案，到一套专利申请材料</h3><div class="flow">${[['folder','新建专利','区分队伍与申请类型'],['file','分步填写','技术内容与人员信息'],['shield','检查专利材料','发现遗漏与格式问题'],['download','导出 Word','独立文书，一键打包']].map(([i,t,d])=>`<div class="flow-item">${icon(i)}<h3>${t}</h3><p>${d}</p></div>`).join('')}</div></div><div class="notice"><h3>${icon('info')} 2026 电子申请格式提醒</h3><p>Word 用于编辑、审阅与归档。电子提交时，说明书等指定文件需使用官方工具转换为 XML 并通过系统校验。</p><a href="https://cponline.cnipa.gov.cn/" target="_blank" rel="noopener">前往国家知识产权局专利业务办理系统</a></div></div>`;}
function projects(){const teams=[...new Set(state.projects.map(p=>p.team).filter(Boolean))];return `<div class="heading-line"><div><div class="eyebrow">PATENT LIBRARY</div><h1>统一管理你的专利申请。</h1><p class="subtitle">每项专利独立保存，申请信息在整套专利文书中自动复用。</p></div><button class="btn primary" data-action="new">${icon('plus')}新建专利</button></div><div class="team-list"><button class="team-filter ${teamFilter==='all'?'active':''}" data-team="all">全部队伍</button>${teams.map(t=>`<button class="team-filter ${teamFilter===t?'active':''}" data-team="${esc(t)}">${esc(t)}</button>`).join('')}</div><div class="section-head"><h2>专利档案</h2>${toolbar()}</div><div class="panel" id="project-results">${table()}</div>`;}
function get(path,obj=current()){return path.split('.').reduce((v,k)=>v?.[k],obj);}
function field(label,path,{placeholder='',hint='',full=false,textarea=false,type='text',options=null,required=false,rows=5,max=null}={}){const val=get(path)??'',id='f-'+path.replaceAll('.','-');return `<div class="field ${full?'full':''}"><label for="${id}">${label}${required?'<em>*</em>':''}</label>${options?`<select id="${id}" data-field="${path}">${options.map(([v,n])=>`<option value="${v}" ${String(val)===String(v)?'selected':''}>${n}</option>`).join('')}</select>`:textarea?`<textarea id="${id}" data-field="${path}" rows="${rows}" placeholder="${esc(placeholder)}">${esc(val)}</textarea>`:`<input id="${id}" data-field="${path}" type="${type}" ${max?`maxlength="${max}"`:''} value="${esc(val)}" placeholder="${esc(placeholder)}" autocomplete="off">`}${hint?`<small>${hint}</small>`:''}${path==='abstract'?`<small class="count ${[...val].length>300?'over':''}" id="abstract-count">${[...val].length} / 300 字（含标点）</small>`:''}</div>`;}
function check(label,path,hint=''){return `<label class="checkbox"><input type="checkbox" data-field="${path}" ${get(path)?'checked':''}><span>${label}${hint?`<small>${hint}</small>`:''}</span></label>`;}
function editor(){const p=current();return `<div class="editor-top"><div><button class="back-link" data-nav="projects">${icon('chevron')}返回专利档案</button><h1>${esc(p.title||'新建专利课题')}</h1><span class="subtitle">${esc(p.team||'尚未设置队伍')} · ${p.type==='utility'?'实用新型专利':'发明专利'}</span></div><div class="toolbar"><button class="btn primary small" data-ai="start">AI 整理专利材料</button><button class="btn small" data-action="duplicate">${icon('copy')}复制课题</button><button class="icon-btn" data-action="delete" aria-label="删除课题">${icon('trash')}</button></div></div>${p.example?'<div class="copy-banner">这是一个通用填写示例，不含真实课题的技术内容或人员信息。可复制后填写自己的资料。</div>':''}<div class="editor-layout"><nav class="steps" aria-label="填写步骤">${steps.map((s,i)=>`<button class="step ${step===i?'active':''}" data-step="${i}" ${step===i?'aria-current="step"':''}><span class="step-n">${i+1}</span>${s}</button>`).join('')}<p class="stephelp">可以随时切换步骤。<br>填写内容自动保存到此浏览器。<br>原始 Word 文件不会被修改。</p></nav><section class="form-panel"><div class="form-intro"><div class="eyebrow">STEP ${String(step+1).padStart(2,'0')} / 06</div><h2>${steps[step]}</h2><p>${['先确定课题归属与申请类型，名称会自动同步到整套文书。','发明人是作出创造性贡献的自然人，申请人是申请专利权的个人或单位。','把技术说清楚：现有问题是什么，你的方案如何解决它。','逐项填写保护范围。系统只做编排，不会替你推断或编造技术特征。','摘要概括技术方案；上传清晰的技术附图，系统自动编号和安排版面。','先导出 Word 审阅版，确认内容与实际分页后，补齐页数并导出归档版。'][step]}</p></div>${[basic,people,technical,claims,drawings,review][step](p)}<div class="step-footer"><button class="btn" data-step="${Math.max(0,step-1)}" ${step===0?'style="visibility:hidden"':''}>上一步</button><span style="font-size:12px;color:#93a19e">自动保存 · 无需手动提交</span>${step<5?`<button class="btn primary" data-step="${step+1}">${step===4?'检查专利材料':'下一步'}</button>`:'<button class="btn" data-nav="projects">返回专利档案</button>'}</div></section><aside class="editor-side"><div class="sidecard"><h3>这份课题的准备进度</h3><span style="font-size:27px;font-weight:600" id="live-progress">${progress(p)}%</span><div class="progress"><span id="live-bar" style="width:${progress(p)}%"></span></div><p>仅统计字段准备情况，不代表技术审查或授权结果。</p></div><div class="sidecard"><h3>你的材料包</h3>${docNames(p).map(n=>`<div class="doc-line">${icon('file')}<span>${n}</span><span>DOCX</span></div>`).join('')}<p>每份文书单独成册，页码独立。请求书使用官方表格。</p></div><div class="sidecard"><h3>${icon('eye')} 正文样式示意</h3><div class="mini-page"><h4>说 明 书</h4><strong id="preview-title">${esc(p.title||'发明创造名称')}</strong><p>技术领域</p><p id="preview-text">[0001] ${esc((p.technicalField||'填写后，在这里查看正文内容示意。').slice(0,100))}</p><div class="fake-line"></div><div class="fake-line"></div><div class="fake-line" style="width:70%"></div></div><p>A4 · 宋体 12 pt · 黑色<br>左上 25 mm · 右下 15 mm<br>此处为样式示意，实际分页以 Word 为准。</p></div></aside></div>`;}
function basic(p){return `<div class="fields">${field('队伍名称','team',{placeholder:'例如：康莱德 · 清源队',required:true})}${field('签署日期','signDate',{type:'date',hint:'按真实签署日期填写，可稍后补齐。'})}${field('发明创造名称','title',{full:true,required:true,placeholder:'一种……装置 / 系统',hint:'通常不超过 25 个字，必要时最多 60 个字。避免品牌名和宣传词。'})}<div class="type-options">${[['invention','发明专利','可针对产品、方法或其改进提出技术方案。'],['utility','实用新型专利','针对产品的形状、构造或其结合，必须有附图。']].map(([v,t,d])=>`<button class="type-option ${p.type===v?'active':''}" data-type="${v}"><strong>${icon(v==='invention'?'leaf':'layers')}${t}</strong><p>${d}</p></button>`).join('')}</div></div><div class="form-divider"></div><h3>本次申请的选项</h3>${check('请求费用减缴，且全体申请人已完成资格备案','feeReduction','仅在已完成备案且符合条件时勾选。')}${check('同日就同样的发明创造申请发明与实用新型','sameDay','需要分别准备并提交两套对应申请，两份请求书中均需声明。')}${p.type==='invention'?`${check('请求早日公布','earlyPublication')}<div class="fields" style="margin-top:20px">${field('实质审查请求','substantive',{full:true,options:[['none','暂不提出（由申请人跟进期限）'],['withApplication','在本次发明请求书中一并提出'],['separate','已提交申请，本次单独提出实审请求']],hint:'一并提出时在请求书勾选；单独提出时另生成《实质审查请求书》。'})}${p.substantive==='separate'?field('已有的专利申请号','applicationNumber',{full:true,required:true,placeholder:'从受理通知书准确填写'}):''}</div>`:''}<div class="hint">目前支持普通国内申请的材料编制。涉及代理机构、优先权、分案、生物材料等特殊事项时，请另行补齐官方表格中的对应栏目。外观设计不在本工作台的模板范围内。</div>`;}
function people(p){return `<div class="form-section-head"><h3>发明人 <span style="color:#8d9b9d;font-weight:400">${p.inventors.length} 位</span></h3><button class="btn small" data-add="inventor">${icon('plus')}添加发明人</button></div>${p.inventors.map((v,i)=>`<div class="person-card"><div class="form-section-head"><h3>第 ${i+1} 发明人${i===0?' · 第一署名':''}</h3>${p.inventors.length>1?`<button class="icon-btn" data-remove="inventor" data-index="${i}" aria-label="移除发明人 ${i+1}">${icon('trash')}</button>`:''}</div><div class="fields">${field('真实姓名',`inventors.${i}.name`,{required:true,max:60})}${field('国籍或地区',`inventors.${i}.country`,{required:true})}${field('身份证件号码',`inventors.${i}.idNumber`,{full:true,required:true,hint:'按证件准确填写；不对外上传，随本地备份保存。'})}</div>${check('请求不公布该发明人姓名',`inventors.${i}.privateName`)}</div>`).join('')}<p class="checklist-note">按真实署名顺序添加。超出请求书栏位时自动生成发明人附页。</p><div class="form-divider"></div><div class="form-section-head"><h3>申请人</h3><button class="btn small" data-add="applicant" ${p.applicants.length>=3?'disabled':''}>${icon('plus')}添加申请人</button></div>${p.applicants.map((v,i)=>`<div class="person-card"><div class="form-section-head"><h3>申请人 ${i+1}${i===0?' · 第一署名':''}</h3>${p.applicants.length>1?`<button class="icon-btn" data-remove="applicant" data-index="${i}" aria-label="移除申请人 ${i+1}">${icon('trash')}</button>`:''}</div><div class="fields">${field('姓名或单位全称',`applicants.${i}.name`,{full:true,required:true})}${field('申请人类型',`applicants.${i}.kind`,{options:['个人','企业','事业单位','机关团体','大专院校','科研单位'].map(t=>[t,t])})}${field('国籍或注册国家 / 地区',`applicants.${i}.country`)}${field('身份证件号码 / 统一社会信用代码',`applicants.${i}.idNumber`,{full:true,required:true})}${field('电话',`applicants.${i}.phone`,{type:'tel',required:true})}${field('电子邮箱',`applicants.${i}.email`,{type:'email'})}${field('经常居所地 / 营业所所在地（国家）',`applicants.${i}.residence`,{full:true})}${field('省 / 自治区 / 直辖市',`applicants.${i}.province`,{required:true,placeholder:'浙江省'})}${field('市县',`applicants.${i}.city`,{required:true,placeholder:'杭州市'})}${field('城区、街道与门牌号',`applicants.${i}.address`,{full:true,required:true,placeholder:'填写可准确投递的完整地址'})}${field('邮政编码',`applicants.${i}.postcode`,{required:true,max:6})}</div></div>`).join('')}<small style="color:#89999e;font-size:12px">当前官方请求书自动填写最多 3 位申请人。申请人与发明人可以不同。</small><div class="form-divider"></div><div class="form-section-head"><h3>联系人</h3><button class="btn small" data-action="copy-contact">使用第一申请人信息</button></div><div class="fields">${field('联系人姓名','contact.name')}${field('联系电话','contact.phone',{type:'tel'})}${field('电子邮箱','contact.email',{full:true,type:'email'})}${field('省 / 自治区 / 直辖市','contact.province')}${field('市县','contact.city')}${field('城区、街道与门牌号','contact.address',{full:true})}${field('邮政编码','contact.postcode',{max:6})}</div><div class="hint">单位申请且未委托代理时，填写一位本单位工作人员作为联系人；个人申请可按实际情况填写。</div>`;}
const technicalHints=[['technicalField','技术领域','本发明涉及……技术领域，具体涉及……。','用一两句话说明所属的具体技术领域。'],['background','背景技术','现有……通常采用……，但在……条件下存在……问题。','客观介绍现有方案及不足，引用文献时写明出处。'],['problem','要解决的技术问题','本发明旨在解决……的问题。','聚焦技术问题，避免只有市场或商业描述。'],['solution','技术方案','该装置包括……，其中……与……连接；工作时……。','写清组成、连接关系、步骤和参数，支持权利要求中的每个特征。'],['benefits','有益效果','通过……结构，能够……。','效果应与技术特征对应；实验数据必须有真实依据。'],['embodiments','具体实施方式','结合图1，本实施例包括……。装配过程为……，工作过程为……。','写到本领域技术人员能够实施的程度。多段内容换行分隔，自动生成段号。']];
function technical(){return `<div class="fields">${technicalHints.map(([k,l,ph,h])=>field(l,k,{full:true,required:true,textarea:true,placeholder:ph,hint:h,rows:k==='embodiments'?9:5})).join('')}</div><div class="hint">“要解决的技术问题、技术方案、有益效果”会合并编排到“${current().type==='utility'?'实用新型':'发明'}内容”部分。附图说明会从你在下一步填写的图注自动整理。</div>`;}
function claims(p){return `<div class="hint" style="margin-top:0">每个卡片是一项权利要求，不必手动加序号。独立权利要求写必要技术特征；从属权利要求引用前面的权项并进一步限定。</div>${p.claims.map((c,i)=>`<div class="claim-card"><div class="form-section-head"><h3>权利要求 ${i+1}</h3>${p.claims.length>1?`<button class="icon-btn" data-remove="claim" data-index="${i}" aria-label="删除权利要求 ${i+1}">${icon('trash')}</button>`:''}</div>${field('权项内容',`claims.${i}.text`,{textarea:true,placeholder:i===0?'一种……，其特征在于，包括……。':`根据权利要求1所述的……，其特征在于，……。`,required:true,hint:i===0?'独立权利要求需要清楚限定技术方案。':'删除或调整权项后，请同步检查引用编号。'})}</div>`).join('')}<button class="btn" data-add="claim">${icon('plus')}增加一项权利要求</button><p class="checklist-note">权项连续编号并自动统计。权利要求的支持性、清楚性和保护范围需要结合完整技术方案审阅。</p>`;}
function drawings(p){return `<div class="fields">${field('说明书摘要','abstract',{full:true,textarea:true,required:true,rows:8,placeholder:'本发明公开了一种……，属于……领域。该方案……，用于……。',hint:'包括名称、领域、问题、技术方案要点与用途。不要写商业宣传或未经验证的效果。'})}</div><div class="form-divider"></div><div class="form-section-head"><h3>说明书附图</h3><span class="pill">${p.figures.length} 张</span></div><p class="subtitle" style="line-height:1.9">上传已绘制的清晰技术图。${p.type==='utility'?'实用新型必须有体现产品形状、构造的附图。':'若技术方案需要附图说明，请在此上传。'}</p>${p.figures.map((f,i)=>`<div class="figure-card" style="margin-top:15px"><img src="${esc(f.dataUrl)}" alt="图 ${i+1} ${esc(f.caption)}"><div class="fields">${field(`图 ${i+1} 的说明`,`figures.${i}.caption`,{full:true,placeholder:'例如：装置的整体结构示意图',required:true})}<small style="font-size:12px;color:#879993">${f.width} × ${f.height} px · ${esc(f.name)}</small><button class="btn small danger" data-remove="figure" data-index="${i}">删除图片</button></div></div>`).join('')}<button class="upload" data-action="upload">${icon('upload')}<strong>选择技术附图</strong><small>PNG / JPG · 单张最多 5 MB · 最多 20 张</small></button>${p.figures.length?`<div class="fields" style="margin-top:24px">${field('指定摘要附图','abstractFigure',{full:true,options:p.figures.map((f,i)=>[String(i+1),`图 ${i+1} · ${esc(f.caption||f.name)}`]),hint:'选择一幅最能反映主要技术特征的独立附图。'})}</div>`:''}<div class="hint">图片等比例放入页面，不拉伸、不自动裁切。每张图独立分页，图号居中；图的说明写入说明书。导出前请核对附图标记与正文一致。</div>`;}
function review(p){const all=issues(p),errors=all.filter(x=>x.severity==='error'),warnings=all.filter(x=>x.severity==='warning');return `<div class="check-header ${errors.length?'warning':''}">${icon(errors.length?'alert':'shield')}<div><h3>${errors.length?`${errors.length} 项信息需要补齐`:'基础填写检查已通过'}</h3><p>${errors.length?'可以先导出草稿，继续补充后再归档。':'可以导出 Word 审阅包，检查内容与实际分页。'}</p></div></div>${all.length?all.map(x=>`<div class="issue">${icon(x.severity==='error'?'alert':'info')}<span>${esc(x.message)}${x.severity==='warning'?'<span style="color:#8e9c94"> · 提醒</span>':''}</span><button class="btn text small" data-step="${x.step}">去填写</button></div>`).join(''):'<div class="check-pass">✓ 已填写必要人员信息、技术说明、权利要求和摘要。</div>'}<div class="export-files"><h3>将生成 ${docNames(p).length} 份可编辑 Word 文书</h3>${docNames(p).map((n,i)=>`<div class="export-file"><div class="file-icon">DOCX</div><div><h3>${n}</h3><p>${n.includes('请求书')?'填入国家知识产权局官方表格':n.includes('附图')?'独立分页 · 图片等比例编排':'宋体 · A4 · 独立页码'}</p></div><span class="pill">${String(i+1).padStart(2,'0')}</span></div>`).join('')}</div><div class="export-actions"><button class="btn primary" data-action="export" data-mode="review">${icon('download')}${errors.length?'导出草稿材料包':'导出 Word 审阅包'}</button><button class="btn" data-action="project-backup">${icon('file')}备份此课题</button></div><div class="hint">导出的是可编辑 Word 材料和检查清单，不会提交专利申请。2026 年电子申请需将指定文件转换为 XML，并在官方系统检查、签名和提交。<a href="https://cponline.cnipa.gov.cn/" target="_blank" rel="noopener">打开官方系统</a></div><div class="form-divider"></div><h3>确认最终分页后，填写请求书文件清单</h3><p class="subtitle" style="margin:12px 0 20px;line-height:1.9">用 Word 或 WPS 打开导出的文书，确认内容、排版和实际页数。这里的页数用于请求书中的文件清单，不会用估算值代填。</p><div class="fields">${[['request','请求书页数'],['abstract','摘要页数'],['claims','权利要求书页数'],['description','说明书页数'],...(p.figures.length?[['drawings','说明书附图页数']]:[]),...(p.type==='invention'&&p.substantive==='separate'?[['substantive','实质审查请求书页数']]:[])].map(([k,n])=>field(n,`pageCounts.${k}`,{type:'number',placeholder:'按实际页数填写'})).join('')}</div><div class="export-actions" style="margin-top:22px"><button class="btn" data-action="export" data-mode="final">${icon('download')}导出已填页数的归档包</button></div><p class="checklist-note">格式检查不代替对新颖性、创造性、充分公开及权利要求保护范围的专业判断。文件实际排版以你的 Word / WPS 及已安装字体为准。</p>`;}
function exportsView(){return `<div class="heading-line"><div><div class="eyebrow">DOCUMENT EXPORTS</div><h1>整套专利材料，一次导出。</h1><p class="subtitle">按专利申请生成请求书、说明书、权利要求书等 Word 文书，整套打包下载。</p></div><button class="btn" data-action="backup">${icon('download')}备份全部专利</button></div><div class="export-grid">${state.projects.map(p=>`<div class="panel export-card"><div class="section-head"><span class="pill">${p.type==='utility'?'实用新型':'发明专利'}</span>${statusPill(p)}</div><h3>${esc(p.title||'未命名课题')}</h3><p>${esc(p.team||'未设置队伍')} · ${docNames(p).length} 份文书</p><div class="progress"><span style="width:${progress(p)}%"></span></div><button class="btn primary" data-review="${p.id}">${icon('shield')}检查并导出材料</button></div>`).join('')||'<div class="empty">暂无课题，先建立一个课题。</div>'}</div><div class="section-head section-gap"><h2>最近导出记录</h2></div><div class="panel">${state.exports.length?state.exports.slice(0,15).map(e=>`<div class="library-row">${icon('file')}<span>${esc(e.title)}<small style="display:block;margin-top:5px">${e.mode==='final'?'归档包':'Word 审阅 / 草稿包'} · ${e.count} 份文书</small></span><small>${fmtDate(e.at)}</small></div>`).join(''):'<div class="empty"><p>还没有导出记录。完成填写后，在课题中点击“检查与导出”。</p></div>'}</div><p class="checklist-note">记录表示本浏览器曾生成下载，不代表已向国家知识产权局提交。再次导出会使用当前课题内容。</p>`;}
function standards(){return `<div class="heading-line"><div><div class="eyebrow">TEMPLATES & STANDARDS</div><h1>专利模板与排版规范。</h1><p class="subtitle">以国家知识产权局官方表格为基础 · 资料核对日期：2026 年 11 月 23 日</p></div></div><div class="standards-grid">${[['file','官方请求书','发明和实用新型使用各自的官方请求书，保留表格布局、栏目与注意事项。'],['layers','正文统一编排','说明书、权利要求书、摘要独立成册。固定页面参数，自动连续编号。'],['shield','先审阅，再申报','Word 用于编辑与审阅。电子提交须按 2026 年要求转换为 XML，并经官方系统校验。']].map(([i,t,d])=>`<div class="panel standard-card">${icon(i)}<h3>${t}</h3><p>${d}</p></div>`).join('')}</div><div class="section-head section-gap"><h2>正文导出排版参数</h2></div><div class="panel"><table class="standard-table"><tbody>${[['纸张与方向','A4 · 210 × 297 mm · 纵向'],['页边距','左侧、顶部 25 mm；右侧、底部 15 mm。'],['正文字体','宋体 · 12 pt（小四）· 黑色；固定行距 22 pt。请求书保留官方表格原有字号和布局。'],['标题与段号','说明书首行居中显示发明创造名称；按技术领域、背景技术、发明/实用新型内容、附图说明、具体实施方式组织；正文段落自动编号。'],['页码与附图','各份正文文书独立页码，底部居中；图像等比例适配，图号居中。摘要附图单独导出。'],['摘要','正文不添加发明名称标题；包括标点符号在内最多 300 字。'],['页数统计','浏览器不能可靠确定 Word 最终分页；请在实际打开文书后填写请求书中的清单页数。']].map(([k,v])=>`<tr><td>${k}</td><td>${v}</td></tr>`).join('')}</tbody></table></div><div class="section-head section-gap"><h2>官方资料与提交入口</h2></div><div class="panel">${[['国家知识产权局 · 专利申请表格下载','当前发明 / 实用新型请求书及正文表格','https://www.cnipa.gov.cn/col/col192/index.html'],['发明专利请求书 · 官方发布页','2025-12-31 版本','https://www.cnipa.gov.cn/art/2025/12/31/art_192_111038.html'],['专利申请相关事项介绍','文件组成与书写要求','https://www.cnipa.gov.cn/art/2020/6/5/art_1517_92472.html'],['2026 年 XML 电子文件清单','说明书、权利要求书、摘要等文件','https://www.cnipa.gov.cn/module/download/downfile.jsp?classid=0&filename=9ee3f4035a3c4c73983da5438d70cb6b.pdf&showname=XML.pdf'],['专利业务办理系统','官方转换工具、校验与申请办理','https://cponline.cnipa.gov.cn/']].map(([t,s,u])=>`<div class="library-row">${icon('book')}<span>${t}</span><small>${s}</small><a class="btn small" href="${u}" target="_blank" rel="noopener">查看</a></div>`).join('')}</div><div class="hint">适用范围：普通国内发明及实用新型申请材料编制。不覆盖外观设计、PCT、优先权、分案及其他特殊申请。技术方案是否具备授权条件，不能仅凭表格完整度判断。</div><div class="section-head section-gap"><h2>材料与模板的复用方式</h2></div><div class="panel"><table class="standard-table"><tbody><tr><td>现有材料</td><td>发明专利请求书、权利要求书、说明书、摘要、说明书附图，以及一份实质审查请求书；已填写的申请材料不能直接当作空白模板。</td></tr><tr><td>复用方式</td><td>保留原文件不变。以官方模板重新建立字段映射，避免旧课题的姓名、日期、权项数和页数混入新的申请。</td></tr><tr><td>示例内容</td><td>工作台提供空白填写示例；真实姓名、证件、技术内容和附图由你自行填写，并保存在当前浏览器。</td></tr></tbody></table></div>`;}
function updateLive(){const p=current();if(!p)return;if($('#live-progress'))$('#live-progress').textContent=progress(p)+'%';if($('#live-bar'))$('#live-bar').style.width=progress(p)+'%';if($('#preview-title'))$('#preview-title').textContent=p.title||'发明创造名称';if($('#preview-text'))$('#preview-text').textContent='[0001] '+(p.technicalField||'填写后，在这里查看正文内容示意。').slice(0,100);if($('#abstract-count')){$('#abstract-count').textContent=[...p.abstract].length+' / 300 字（含标点）';$('#abstract-count').classList.toggle('over',[...p.abstract].length>300);}}
function modal(html){const d=$('#modal');d.innerHTML=html;if(!d.open)d.showModal();}
function newModal(){modal(`<h2>开始一项新的专利申请</h2><p>为康莱德队伍建立独立的专利申请档案。</p><form id="new-form"><div class="fields"><div class="field full"><label for="new-title">专利 / 发明创造名称</label><input id="new-title" name="title" required placeholder="例如：一种便携式水质检测装置" maxlength="60"></div><div class="field full"><label for="new-team">康莱德队伍</label><input id="new-team" name="team" required placeholder="例如：康莱德 · 清源队" maxlength="80"></div><div class="field full"><label for="new-type">专利类型</label><select id="new-type" name="type"><option value="invention">发明专利</option><option value="utility">实用新型专利</option></select></div></div><div class="actions"><button type="button" class="btn" data-action="close-modal">取消</button><button type="submit" class="btn primary">创建专利</button></div></form>`);}
function download(blob,name){const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);}
function cleanName(s){return (s||'未命名课题').replace(/[<>:"/\\|?*\x00-\x1f]/g,'_').slice(0,90);}
function backup(one=false){const payload={format:'zhixu-patent-studio',version:1,exportedAt:new Date().toISOString(),projects:one?[current()]:state.projects,exports:one?state.exports.filter(e=>e.projectId===activeId):state.exports};download(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),`${one?cleanName(current().title):'康莱德工坊-全部专利'}-备份.json`);toast('备份已生成，请妥善保存，其中包含课题与人员信息。');}
function normalizeProject(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('课题结构无效');const p=blank();const str=(x,max=100000)=>typeof x==='string'?x.slice(0,max):'';for(const k of ['title','team','technicalField','background','problem','solution','benefits','embodiments','abstract','applicationNumber','signDate'])p[k]=str(raw[k]);p.title=p.title.slice(0,200);p.team=p.team.slice(0,200);p.type=raw.type==='utility'?'utility':'invention';for(const k of ['earlyPublication','feeReduction','sameDay','example'])p[k]=raw[k]===true;p.substantive=['none','withApplication','separate'].includes(raw.substantive)?raw.substantive:'none';p.inventors=(Array.isArray(raw.inventors)?raw.inventors:[person()]).slice(0,30).map(v=>({name:str(v.name,60),country:str(v.country,60),idNumber:str(v.idNumber,60),privateName:v.privateName===true}));if(!p.inventors.length)p.inventors=[person()];p.applicants=(Array.isArray(raw.applicants)?raw.applicants:[applicant()]).slice(0,3).map(v=>Object.fromEntries(Object.keys(applicant()).map(k=>[k,str(v[k],500)])));if(!p.applicants.length)p.applicants=[applicant()];p.contact=Object.fromEntries(Object.keys(contact()).map(k=>[k,str(raw.contact?.[k],500)]));p.claims=(Array.isArray(raw.claims)?raw.claims:[{text:''}]).slice(0,100).map(c=>({text:str(c.text)}));if(!p.claims.length)p.claims=[{text:''}];p.figures=(Array.isArray(raw.figures)?raw.figures:[]).slice(0,20).map(f=>{if(!/^data:image\/(png|jpeg);base64,[A-Za-z0-9+/=]+$/.test(f.dataUrl||'')||f.dataUrl.length>7500000)throw Error('备份含无效或过大的附图');return {name:str(f.name,200),caption:str(f.caption,2000),dataUrl:f.dataUrl,width:Math.max(1,Math.min(30000,+f.width||1)),height:Math.max(1,Math.min(30000,+f.height||1))};});p.abstractFigure=Math.max(1,Math.min(20,+raw.abstractFigure||1));for(const k of Object.keys(p.pageCounts))p.pageCounts[k]=/^\d{1,4}$/.test(String(raw.pageCounts?.[k]??''))?String(raw.pageCounts[k]):'';return p;}
async function importBackup(file){if(!file)return;if(file.size>100*1024*1024)throw Error('备份文件超过 100 MB');const raw=JSON.parse(await file.text());if(raw.format!=='zhixu-patent-studio'||raw.version!==1||!Array.isArray(raw.projects)||raw.projects.length>300)throw Error('请选择康莱德工坊导出的有效 JSON 备份');const ps=raw.projects.map(normalizeProject);if(!ps.length)throw Error('备份中没有课题');window.pendingImport=ps;modal(`<h2>导入 ${ps.length} 个课题</h2><p>将作为新课题添加到当前专利档案，已有材料不会被覆盖。导出历史不合并。</p><div class="actions"><button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="confirm-import">确认导入</button></div>`);}
async function upload(files){const p=current();if(!p)return;let added=0;for(const f of files){if(p.figures.length>=20){toast('最多上传 20 张附图');break;}if(!['image/png','image/jpeg'].includes(f.type)||f.size>5*1024*1024){toast(`${f.name}：请使用 5 MB 以内的 PNG 或 JPG`);continue;}const dataUrl=await new Promise((r,j)=>{const fr=new FileReader();fr.onload=()=>r(fr.result);fr.onerror=j;fr.readAsDataURL(f);});const im=await new Promise((r,j)=>{const i=new Image();i.onload=()=>r(i);i.onerror=()=>j(Error('图片无法读取'));i.src=dataUrl;});p.figures.push({name:f.name,caption:'',dataUrl,width:im.naturalWidth,height:im.naturalHeight});added++;}touch();render();toast(`已添加 ${added} 张附图，请填写每张图的说明。`);}
async function exportProject(mode){const p=current();if(!p)return;const errs=issues(p).filter(x=>x.severity==='error');if(mode==='final'){if(errs.length){toast(`请先补齐 ${errs.length} 项必要信息，再导出归档包。`);return;}const need=['request','claims','description','abstract',...(p.figures.length?['drawings']:[]),...(p.type==='invention'&&p.substantive==='separate'?['substantive']:[])];if(need.some(k=>!/^\d+$/.test(String(p.pageCounts[k]))||+p.pageCounts[k]<1)){toast('请填写各份文书的实际页数，不能填 0 或小数。');return;}}
if(!window.PatentExport?.generate){toast('Word 引擎尚未加载完成，请稍后再试。');return;}const buttons=[...document.querySelectorAll('[data-action="export"]')];buttons.forEach(b=>b.disabled=true);toast('正在套用模板并生成 Word 文书…');try{await persist();const draft=errs.length>0;const snapshot=structuredClone(p);const files=await PatentExport.generate(snapshot,{draft});const zip=new JSZip();for(const f of files)zip.file(f.name,f.blob);const report=['康莱德工坊 · 专利材料检查清单',`课题：${p.title}`,`队伍：${p.team}`,`类型：${p.type==='utility'?'实用新型':'发明专利'}`,`生成时间：${new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}`,`导出用途：${mode==='final'?'已填页数的归档包':'Word 审阅 / 草稿包'}`,'','待检查项目：',...issues(p).map(x=>`- ${x.message}`),'','提交前确认：','1. 在 Word/WPS 中检查全部页面、字体、公式、附图与页码；不同设备的字体可影响分页。','2. 请求书页数按照实际提交材料填写，不含无需提交的注意事项页；请结合具体提交方式复核。','3. 全体申请人按要求签字或盖章；核对人员信息及权利归属。','4. 2026 年电子申请中的指定文件须由官方工具转换为 XML 并校验；本材料包不是官方电子申报包。','5. 技术内容、权利要求与图片需由申请人及专业人员核实。','官方表格：https://www.cnipa.gov.cn/col/col192/index.html','官方系统：https://cponline.cnipa.gov.cn/'];zip.file('材料检查清单.txt',report.join('\n'));zip.file('课题备份.json',JSON.stringify({format:'zhixu-patent-studio',version:1,projects:[snapshot],exports:[]},null,2));const blob=await zip.generateAsync({type:'blob',compression:'DEFLATE'});download(blob,`${cleanName(p.title)}-${mode==='final'?'归档包':draft?'草稿材料包':'Word审阅包'}.zip`);state.exports.unshift({projectId:p.id,title:p.title,at:new Date().toISOString(),mode,count:files.length});state.exports=state.exports.slice(0,100);await persist();toast(`已生成 ${files.length} 份 Word 文书与检查清单。`);}catch(e){console.error(e);toast('生成失败：'+e.message);}finally{buttons.forEach(b=>b.disabled=false);}}
function setField(target){const p=current();if(!p)return;const parts=target.dataset.field.split('.');if(parts.some(k=>['__proto__','constructor','prototype'].includes(k)))return;let o=p;for(const k of parts.slice(0,-1)){if(o[k]==null)return;o=o[k];}o[parts.at(-1)]=target.type==='checkbox'?target.checked:target.value;touch();if(['substantive'].includes(target.dataset.field))render();}
document.addEventListener('input',e=>{if(e.target.matches('[data-field]')&&e.target.type!=='checkbox'&&e.target.tagName!=='SELECT')setField(e.target);if(e.target.id==='search'){search=e.target.value;$('#project-results').innerHTML=table();}});
document.addEventListener('change',e=>{if(e.target.matches('[data-field]')&&(e.target.type==='checkbox'||e.target.tagName==='SELECT'))setField(e.target);if(e.target.id==='type-filter'){typeFilter=e.target.value;$('#project-results').innerHTML=table();}if(e.target.id==='import-file'){importBackup(e.target.files[0]).catch(er=>toast('导入失败：'+er.message));e.target.value='';}if(e.target.id==='image-file'){upload([...e.target.files]).catch(er=>toast('图片读取失败：'+er.message));e.target.value='';}});
document.addEventListener('submit',async e=>{if(e.target.id!=='new-form')return;e.preventDefault();const f=new FormData(e.target),p=blank();p.title=f.get('title').trim();p.team=f.get('team').trim();p.type=f.get('type');if(!p.title||!p.team)return;state.projects.push(p);activeId=p.id;step=0;view='editor';$('#modal').close();queueSave();render();});
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-nav]');if(!b)return;try{if(b.dataset.nav){view=b.dataset.nav;search='';typeFilter='all';teamFilter='all';render();window.scrollTo(0,0);return;}if(b.dataset.open||b.dataset.review){activeId=b.dataset.open||b.dataset.review;step=b.dataset.review?5:0;view='editor';render();window.scrollTo(0,0);return;}if(b.dataset.step!==undefined){step=+b.dataset.step;render();window.scrollTo(0,0);return;}if(b.dataset.team!==undefined){teamFilter=b.dataset.team;render();return;}const p=current();if(b.dataset.type){p.type=b.dataset.type;touch();render();return;}if(b.dataset.add){const k=b.dataset.add;if(k==='inventor'&&p.inventors.length<30)p.inventors.push(person());if(k==='applicant'&&p.applicants.length<3)p.applicants.push(applicant());if(k==='claim'&&p.claims.length<100)p.claims.push({text:''});touch();render();return;}if(b.dataset.remove){const names={inventor:'inventors',applicant:'applicants',claim:'claims',figure:'figures'},key=names[b.dataset.remove],idx=+b.dataset.index;if(key!=='figures'&&p[key].length<=1)return;p[key].splice(idx,1);if(key==='figures')p.abstractFigure=Math.min(+p.abstractFigure||1,p.figures.length||1);touch();render();if(key==='claims'||key==='figures')toast('编号已重新排列，请核对正文中的引用。');return;}
switch(b.dataset.action){case'new':newModal();break;case'close-modal':$('#modal').close();break;case'backup':backup();break;case'project-backup':backup(true);break;case'import':$('#import-file').click();break;case'confirm-import':state.projects.push(...window.pendingImport);window.pendingImport=null;await persist();$('#modal').close();view='projects';render();toast('课题已导入并保存到此浏览器。');break;case'copy-contact':{const a=p.applicants[0];for(const k of Object.keys(p.contact))p.contact[k]=a[k]||'';touch();render();toast('已复制第一申请人的联系信息。');break;}case'duplicate':{const clone=structuredClone(p);clone.id=crypto.randomUUID();clone.example=false;clone.title=p.title+'（副本）';clone.createdAt=new Date().toISOString();clone.updatedAt=clone.createdAt;clone.pageCounts=blank().pageCounts;state.projects.push(clone);activeId=clone.id;touch();render();toast('已创建独立副本，人员和技术内容一并复制。');break;}case'delete':modal(`<h2>删除这个课题？</h2><p>“${esc(p.title||'未命名课题')}”将从当前浏览器移除。请确认已有所需备份。</p><div class="actions"><button class="btn" data-action="close-modal">保留课题</button><button class="btn danger" data-action="confirm-delete">删除课题</button></div>`);break;case'confirm-delete':state.projects=state.projects.filter(x=>x.id!==activeId);await persist();activeId=null;$('#modal').close();view='projects';render();toast('课题已删除。');break;case'upload':$('#image-file').click();break;case'export':await exportProject(b.dataset.mode);break;}
}catch(er){console.error(er);toast('操作未完成：'+er.message);}});
function initAI(){window.PatentAI?.init({
  render,toast,download,issues,
  saveGenerated:async artifact=>{if(!state.projects.some(p=>p.id===artifact.project.id)){state.projects.push(artifact.project);state.exports.unshift({projectId:artifact.project.id,title:artifact.project.title,at:new Date().toISOString(),mode:'ai',count:artifact.count});state.exports=state.exports.slice(0,100);}activeId=artifact.project.id;view='editor';step=5;queueSave();await persist();},
  project:id=>state.projects.find(p=>p.id===id),
  ensureProject:team=>{if(view==='editor'&&current())return current();const p=blank();p.team=team;state.projects.push(p);activeId=p.id;view='editor';step=0;queueSave();render();return p;},
  changed:p=>{p.updatedAt=new Date().toISOString();queueSave();},save:persist
});}
window.addEventListener('beforeunload',e=>{if(unsaved){persist().catch(()=>{});e.preventDefault();e.returnValue='';}});
(async()=>{try{db=await openDB();const saved=await readDB();if(saved&&Array.isArray(saved.projects)){state=saved;state.exports??=[];}else{state={projects:[sample()],exports:[]};await writeDB(state);}render();initAI();}catch(e){$('#app').innerHTML=`<div class="error-screen"><h1>浏览器存储暂不可用</h1><p>请允许此网站使用浏览器存储后刷新页面。你的原始文件不受影响。</p><p>${esc(e.message)}</p><button class="btn primary" onclick="location.reload()">重新加载</button></div>`;}})();
